package cli

import (
	"bytes"
	"strings"
	"testing"
)

// newTestProgressBar builds a progressBar with rendering forced on so the
// production guard `interactive.IsTerminalWriter(w)` (which is false for a
// *bytes.Buffer) does not short-circuit Render/Finish.
func newTestProgressBar(w *bytes.Buffer, total int) *progressBar {
	return &progressBar{
		w:       w,
		label:   "label",
		total:   total,
		width:   8,
		enabled: true,
	}
}

func TestProgressBarFinishCompletedLeavesBarVisibleAndAppendsNewline(t *testing.T) {
	t.Parallel()
	var buf bytes.Buffer
	p := newTestProgressBar(&buf, 2)
	p.Increment()
	p.Increment()
	p.Finish()

	out := buf.String()
	if !strings.Contains(out, "100%") {
		t.Fatalf("expected rendered bar at 100%% to remain in output, got %q", out)
	}
	if !strings.HasSuffix(out, "\n") {
		t.Fatalf("expected Finish to terminate the bar with a newline, got %q", out)
	}
	if strings.Contains(out, "\r\x1b[K") {
		t.Fatalf("Finish on a completed bar must not emit the clear-line sequence, got %q", out)
	}
}

func TestProgressBarFinishIsIdempotent(t *testing.T) {
	t.Parallel()
	var buf bytes.Buffer
	p := newTestProgressBar(&buf, 1)
	p.Increment()
	p.Finish()
	first := buf.String()
	p.Finish()
	if buf.String() != first {
		t.Fatalf("second Finish must not write again; got %q after second call, want %q", buf.String(), first)
	}
}

func TestProgressBarFinishEarlyExitClearsBar(t *testing.T) {
	t.Parallel()
	var buf bytes.Buffer
	p := newTestProgressBar(&buf, 5)
	p.Increment()
	p.Finish()
	out := buf.String()
	if !strings.HasSuffix(out, "\r\x1b[K") {
		t.Fatalf("Finish before completion must end with the clear-line sequence, got %q", out)
	}
	if strings.HasSuffix(out, "\n") {
		t.Fatalf("Finish before completion must not append a newline (the bar is being erased), got %q", out)
	}
}

